{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0003",
          "reason": "This is a self-report of office status and commander-in-chief role; it is constitutional context, not 2022 nuclear-risk conduct."
        },
        {
          "evidence_id": "E0011",
          "reason": "This is historical disarmament baseline, not AMLO-specific 2022 action."
        }
      ],
      "material_gaps": [],
      "reason": "The package fairly separates inherited non-nuclear posture and civilian safeguards from AMLO's own 2022 conduct. It does not overclaim nuclear authority, brinkmanship, or command-and-control behavior that the evidence does not show."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package cleanly presents Mexico's limited-exposure diplomatic role in the Ukraine crisis, with restraint, lawful-peace signaling, and counterevidence preserved. It does not confuse diplomatic positioning with battlefield conduct."
    },
    {
      "chapter_id": "3B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0031",
          "reason": "This is a 2021 state-level protest incident published in 2022; it should be treated as retrospective pattern context, not a fresh 2022 federal order."
        },
        {
          "evidence_id": "E0034",
          "reason": "This is political polemic against conservatives, not a direct call for violence; it should be used only as stigmatizing rhetoric evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Federal command attribution is still thin for several state-level protest, journalist, and policing incidents.",
          "lenses": ["3B.1", "3B.2", "3B.4", "3B.9"],
          "best_source_or_query_direction": "Federal and state investigation records, ombuds findings, and court rulings tied to the named incidents.",
          "why_it_matters": "The severity picture is strong, but the ruler-attribution boundary is what could move the chapter balance."
        }
      ],
      "reason": "The package is substantively strong on violence, impunity, militarization, and press repression, but several items are state-level, retrospective, or only indirectly tied to federal authority. That attribution boundary is material enough to keep the chapter under manual review."
    },
    {
      "chapter_id": "4B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0048",
          "reason": "This Pegasus evidence is partly retrospective to 2019-2021; it should be used as continuing-surveillance context, not as a new 2022 incident."
        },
        {
          "evidence_id": "E0049",
          "reason": "This is a secondary advocacy synthesis of a forensic investigation; it is useful, but should not be treated as a stand-alone finding on command responsibility."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent evidence that AMLO strengthened courts, the INE, INAI, or other checks is still weak compared with the evidence of media hostility and electoral-pressure attempts.",
          "lenses": ["4B.4", "4B.8"],
          "best_source_or_query_direction": "Court, legislative, and autonomy-body records from 2022.",
          "why_it_matters": "Without a stronger pro-constraint counterweight, the package is tilted toward erosion and media pressure."
        }
      ],
      "reason": "The package fairly captures anti-pluralist pressure, media hostility, surveillance concerns, and contestation over electoral reform. The remaining weakness is the lack of a comparably strong counter-record on institutional strengthening, which is a real gap but not enough to invalidate the chapter."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0051",
          "reason": "This is macro context on inflation and fiscal stance; it should not be read as direct proof of AMLO's competence without the other policy evidence."
        },
        {
          "evidence_id": "E0055",
          "reason": "Banxico is independent, so this is primarily macro context rather than a ruler-attributed policy action."
        },
        {
          "evidence_id": "E0064",
          "reason": "This is an external remittance driver, useful as a counterweight, but not AMLO-driven performance evidence."
        }
      ],
      "material_gaps": [],
      "reason": "The package is balanced and attribution-aware. It separates policy choices, external tailwinds, and legislative constraints, and it does not confuse outcome improvement with full ruler ownership."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0077",
          "reason": "This is a retrospective government estimate of minimum-wage effects; it is useful context, not contemporaneous proof of 2022 welfare impact."
        },
        {
          "evidence_id": "E0086",
          "reason": "This is also a retrospective model-based estimate and should be treated cautiously as attribution context rather than direct outcome proof."
        }
      ],
      "material_gaps": [],
      "reason": "The dossier fairly presents broad welfare expansion, service creation, and distributional limits. It also preserves the distinction between coverage and impact, and between government claims and independent assessments."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0091",
          "reason": "This is a self-reported income/declaration statement; it is not independent verification of assets or outside income."
        },
        {
          "evidence_id": "E0094",
          "reason": "This is an indirect family-scrutiny response about Pío López Obrador, not proof of AMLO's own self-dealing."
        },
        {
          "evidence_id": "E0095",
          "reason": "This is a contested family-allegation episode; it should be used only as scrutiny-response evidence, not as a finding of personal corruption."
        },
        {
          "evidence_id": "E0098",
          "reason": "This concerns disputed government evidence in Ayotzinapa; it is relevant to truthfulness and accountability, but not a validated finding of deliberate personal deception."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct personal-nexus evidence on self-enrichment, hidden ownership, or preferential benefit remains thin, and several items are still allegations or self-reports.",
          "lenses": ["7B.3", "7B.4", "7B.5", "7B.9"],
          "best_source_or_query_direction": "Asset declarations, procurement and contract records, and independent findings involving close associates.",
          "why_it_matters": "Without stronger personal-nexus proof, the chapter can describe scrutiny, rhetoric, and transparency conflict, but not a fully grounded corruption pattern."
        }
      ],
      "reason": "The package captures truthfulness disputes, scrutiny behavior, and anti-press conduct, but the evidence on personal enrichment and close-associate benefit remains thin. That is a material unresolved issue for this chapter."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0102",
          "reason": "This is an announcement, not delivery evidence; it should support program intent, not be treated as proof of execution."
        },
        {
          "evidence_id": "E0110",
          "reason": "This is a retrospective outcome attribution from the World Bank; it is useful, but it is not full ownership of the poverty decline."
        },
        {
          "evidence_id": "E0111",
          "reason": "This is an external remittance tailwind and should be treated as context against over-attributing 2022 gains to AMLO."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent audit-level evidence on on-time, on-budget delivery and the causal split between AMLO policy and external tailwinds is still incomplete.",
          "lenses": ["8B.7", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Project audits, procurement records, and independent implementation evaluations from 2022.",
          "why_it_matters": "Competence can be overstated if announcements and partial rollouts are treated as full execution."
        }
      ],
      "reason": "The package is broadly fair on program, implementation, and outcomes. It also distinguishes declared goals from independent evidence and avoids treating external labor-market and remittance effects as pure ruler competence."
    }
  ]
}
